import pytest

from your_module import partial as custom_partial  # update import as needed


# Happy paths

def test_returns_callable_wrapper_and_underlying_return_value():
    def fn():
        return "result"

    wrapper = custom_partial(fn)

    assert callable(wrapper)
    assert wrapper() == "result"


def test_prepends_bound_positional_arguments_to_call_time_arguments():
    def collect(*args):
        return args

    wrapper = custom_partial(collect, "bound-1", "bound-2")

    assert wrapper("runtime-1", "runtime-2") == (
        "bound-1",
        "bound-2",
        "runtime-1",
        "runtime-2",
    )


def test_binds_keyword_arguments():
    def greet(*, greeting, name):
        return f"{greeting}, {name}!"

    wrapper = custom_partial(greet, greeting="Hello")

    assert wrapper(name="Ada") == "Hello, Ada!"


def test_combines_bound_and_call_time_args_and_kwargs():
    def fn(a, b, c=0, *, d=0):
        return a, b, c, d

    wrapper = custom_partial(fn, 1, c=3)

    assert wrapper(2, d=4) == (1, 2, 3, 4)


def test_call_time_keyword_overrides_bound_keyword():
    def fn(**kwargs):
        return kwargs

    wrapper = custom_partial(fn, color="red", size="M")

    assert wrapper(color="blue") == {
        "color": "blue",
        "size": "M",
    }


# Edge cases

def test_keyword_override_does_not_persist_between_calls():
    def get_mode(**kwargs):
        return kwargs["mode"]

    wrapper = custom_partial(get_mode, mode="default")

    assert wrapper(mode="override") == "override"
    assert wrapper() == "default"


def test_no_bound_arguments_behaves_like_original_function():
    def subtract(a, b=0):
        return a - b

    wrapper = custom_partial(subtract)

    assert wrapper(10, b=3) == 7


def test_all_arguments_can_be_bound_up_front():
    def add(a, b):
        return a + b

    wrapper = custom_partial(add, 2, 5)

    assert wrapper() == 7


def test_supports_varargs_and_varkwargs():
    def collect(*args, **kwargs):
        return args, kwargs

    wrapper = custom_partial(collect, 1, 2, x=3)

    assert wrapper(4, x=9, y=5) == (
        (1, 2, 4),
        {"x": 9, "y": 5},
    )


def test_supports_callable_objects():
    class Multiplier:
        def __call__(self, a, b):
            return a * b

    wrapper = custom_partial(Multiplier(), 6)

    assert wrapper(7) == 42


# Error cases

def test_missing_required_argument_raises_type_error():
    def requires_two_args(a, b):
        return a + b

    wrapper = custom_partial(requires_two_args, 1)

    with pytest.raises(TypeError):
        wrapper()


def test_unexpected_keyword_argument_raises_type_error():
    def takes_one_arg(a):
        return a

    wrapper = custom_partial(takes_one_arg, 1)

    with pytest.raises(TypeError):
        wrapper(extra=True)


def test_duplicate_argument_from_bound_positional_and_runtime_keyword_raises_type_error():
    def fn(a):
        return a

    wrapper = custom_partial(fn, 1)

    with pytest.raises(TypeError, match="multiple values"):
        wrapper(a=2)


def test_duplicate_argument_from_bound_keyword_and_runtime_positional_raises_type_error():
    def fn(a):
        return a

    wrapper = custom_partial(fn, a=1)

    with pytest.raises(TypeError, match="multiple values"):
        wrapper(2)


def test_underlying_exception_is_propagated():
    class CustomError(Exception):
        pass

    def boom():
        raise CustomError("boom")

    wrapper = custom_partial(boom)

    with pytest.raises(CustomError, match="boom"):
        wrapper()


def test_non_callable_fn_raises_type_error_when_invoked():
    wrapper = custom_partial(123, "arg")

    with pytest.raises(TypeError):
        wrapper()
